// SPTS — Dark mode toggle.
// The initial theme is applied by a tiny inline script in <head>
// (before first paint, to avoid a flash of the wrong theme). This
// file only wires up the toggle button and reloads the page so any
// theme-aware content generated by PHP/JS (e.g. Chart.js) re-renders
// correctly for the new theme instead of going stale in place.
function toggleTheme() {
    var current = document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'dark' : 'light';
    var next = current === 'dark' ? 'light' : 'dark';
    try { localStorage.setItem('spts-theme', next); } catch (e) {}
    location.reload();
}

function sptsSyncThemeIcon() {
    var theme = document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'dark' : 'light';
    document.querySelectorAll('.theme-toggle-icon').forEach(function (el) {
        el.classList.toggle('bi-sun-fill', theme === 'dark');
        el.classList.toggle('bi-moon-stars-fill', theme !== 'dark');
    });
}

document.addEventListener('DOMContentLoaded', sptsSyncThemeIcon);
